code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The 2 stripe is the direction of travel; the non-background object
    # slides against an outer stripe and an 8 stripe marks its far edge.
    bg = Counter(v for row in grid for v in row if v != 2).most_common(1)[0][0]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (2, bg)]
    if not pts:
        return out
    rs = [r for r, c in pts]
    cs = [c for r, c in pts]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    # Find a full stripe of 2s.
    stripe = None
    if all(v == 2 for v in grid[0]):
        stripe = ('top', 0)
    elif all(v == 2 for v in grid[-1]):
        stripe = ('bottom', h - 1)
    elif all(grid[r][0] == 2 for r in range(h)):
        stripe = ('left', 0)
    elif all(grid[r][-1] == 2 for r in range(h)):
        stripe = ('right', w - 1)
    else:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                stripe = ('internal_vertical', c)
                break
        if stripe is None:
            for r in range(h):
                if all(v == 2 for v in grid[r]):
                    stripe = ('internal_horizontal', r)
                    break
    dr = dc = 0
    if stripe:
        side, k = stripe
        if side == 'top': dr = 1 - r0
        elif side == 'bottom': dr = (h - 2) - r1
        elif side == 'left': dc = 1 - c0
        elif side == 'right': dc = (w - 2) - c1
        # A non-edge stripe is a divider: retain the object and mark its
        # outer edge (the demonstrated internal-divider case).
    # Clear original object, then re-place it at its translated coordinates.
    for r, c in pts:
        out[r][c] = bg
    for r, c in pts:
        out[r + dr][c + dc] = grid[r][c]
    nr0, nr1, nc0, nc1 = r0 + dr, r1 + dr, c0 + dc, c1 + dc
    if stripe:
        side, k = stripe
        if side in ('top', 'bottom'):
            rr = nr1 + 1 if side == 'top' else nr0 - 1
            if 0 <= rr < h:
                for c in range(w): out[rr][c] = 8
        elif side in ('left', 'right'):
            cc = nc1 + 1 if side == 'left' else nc0 - 1
            if 0 <= cc < w:
                for r in range(h): out[r][cc] = 8
        elif side == 'internal_vertical':
            cc = nc1 + 1
            if 0 <= cc < w:
                for r in range(h): out[r][cc] = 8
        elif side == 'internal_horizontal':
            rr = nr1 + 1
            if 0 <= rr < h:
                for c in range(w): out[rr][c] = 8
    return out
'''
